stageCss:
#stage .gh-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .gh-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .gh-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .gh-mark svg{ width:25px; height:25px; }
#stage .gh-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .gh-count{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .gh-count b{
  color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:700;
  font-variant-numeric:tabular-nums;
}
#stage .gh-count i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .gh-verdict{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid var(--border); background:rgba(14,20,32,.7);
  transition:border-color .3s ease, background .3s ease;
}
#stage .gh-verdict i{
  width:10px; height:10px; border-radius:50%; background:var(--text-dim);
  animation:msd-breathe 2s ease-in-out infinite;
}
#stage .gh-verdict b{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .gh-verdict.on{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.12); }
#stage .gh-verdict.on i{ background:var(--success); box-shadow:0 0 12px var(--success); }
#stage .gh-verdict.on b{ color:var(--success); }

/* ============================= SCENE STACK ============================= */
#stage .gh-body{ position:relative; flex:1; min-height:0; }
#stage .gh-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .gh-sc.on{ opacity:1; transform:none; }
#stage .gh-sc.whip{ animation:gh-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .gh-board{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* ------------------------------------------------------------- question -- */
#stage .gh-q{
  height:186px; flex-shrink:0; display:flex; flex-direction:column; justify-content:center; gap:12px;
  padding:18px 24px; border-radius:26px;
  background:radial-gradient(circle at 12% 0%, rgba(58,160,255,.14), transparent 62%), rgba(20,27,43,.7);
  border:2px solid rgba(58,160,255,.45);
  transition:box-shadow .3s ease;
}
#stage .gh-q.hot{ box-shadow:0 0 0 1px rgba(58,160,255,.25), 0 0 60px rgba(58,160,255,.16); }
#stage .gh-qn{
  align-self:flex-start; padding:6px 15px; border-radius:8px;
  background:rgba(58,160,255,.18); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .gh-qt{ color:#fff; font-size:34px; font-weight:800; letter-spacing:-.6px; line-height:1.15; }
#stage .gh-qa{
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis; transition:color .3s ease;
}
#stage .gh-qa.grid{ color:var(--warn); }
#stage .gh-qa.hubs{ color:var(--accent-cyan); }

/* ---------------------------------------------------------- the columns -- */
#stage .gh-cols{ flex:1; min-height:0; display:flex; gap:14px; }
#stage .gh-col{
  flex:1; min-width:0; display:flex; flex-direction:column; gap:12px;
  padding:18px 16px; border-radius:26px;
  background:rgba(20,27,43,.6); border:2px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease, opacity .3s ease, filter .3s ease;
}
#stage .gh-col.grid{ border-color:rgba(240,166,74,.42); }
#stage .gh-col.hubs{ border-color:rgba(34,211,238,.42); }
#stage .gh-col.grid.lead{ box-shadow:0 0 0 1px rgba(240,166,74,.24), 0 0 60px rgba(240,166,74,.16); }
#stage .gh-col.hubs.lead{ box-shadow:0 0 0 1px rgba(34,211,238,.24), 0 0 60px rgba(34,211,238,.16); }
#stage .gh-col.fade{ opacity:.45; filter:saturate(.35); }
#stage .gh-col-h{ display:flex; align-items:center; gap:12px; }
#stage .gh-col-ic{ font-size:30px; flex-shrink:0; }
#stage .gh-col-h b{ color:#fff; font-size:26px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }

/* --------------------------------------------------------- the mechanism -- */
#stage .gh-mech{
  position:relative; height:96px; flex-shrink:0; border-radius:18px;
  display:flex; align-items:center; gap:12px; padding:0 16px;
  background:rgba(14,20,32,.72); border:1.5px solid var(--border);
}
#stage .gh-mech-t{
  margin-left:auto; color:var(--text-dim); font-family:var(--font-mono);
  font-size:16px; font-weight:600; white-space:nowrap;
}
#stage .gh-bell{ font-size:30px; flex-shrink:0; animation:gh-shake 2.4s ease-in-out infinite; }
#stage .gh-outs{ display:flex; flex-direction:column; gap:7px; }
#stage .gh-outs .gh-o{
  display:block; width:44px; height:6px; border-radius:3px;
  background:var(--warn); box-shadow:0 0 10px rgba(240,166,74,.5);
  animation:gh-push 1.4s linear infinite;
}
#stage .gh-outs .gh-o:nth-child(2){ animation-delay:.2s; }
#stage .gh-outs .gh-o:nth-child(3){ animation-delay:.4s; }
#stage .gh-cells{ display:flex; align-items:center; gap:5px; }
#stage .gh-cells i{
  display:block; width:26px; height:34px; border-radius:6px;
  background:rgba(34,211,238,.2); border:1px solid rgba(34,211,238,.45);
}
/* The cursor is what makes the tape a tape: it moves without consuming. */
#stage .gh-cursor{
  position:absolute; left:22px; bottom:14px; width:0; height:0;
  border-left:8px solid transparent; border-right:8px solid transparent;
  border-bottom:11px solid var(--accent-cyan);
  animation:gh-scrub 3.4s ease-in-out infinite;
}

#stage .gh-col-list{ display:flex; flex-direction:column; gap:9px; }
#stage .gh-r{
  display:flex; align-items:center; gap:10px;
  padding:11px 12px; border-radius:12px; white-space:nowrap; overflow:hidden;
  background:rgba(14,20,32,.72); border:1.5px solid var(--border); color:var(--text-primary);
  font-family:var(--font-mono); font-size:17px; font-weight:600;
}
#stage .gh-r i{
  flex-shrink:0; width:22px; height:22px; border-radius:6px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(139,149,167,.16); color:var(--text-dim);
  font-style:normal; font-size:14px; font-weight:800;
}
#stage .gh-col.grid .gh-r i{ background:rgba(240,166,74,.18); color:var(--warn); }
#stage .gh-col.hubs .gh-r i{ background:rgba(34,211,238,.18); color:var(--accent-cyan); }

#stage .gh-note{
  height:112px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:22px;
  background:rgba(20,27,43,.6); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .gh-note.both{
  border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.08);
}
#stage .gh-note-ic{
  width:48px; height:48px; border-radius:14px; flex-shrink:0; font-size:25px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.3);
}
#stage .gh-note-t{ color:var(--text-primary); font-size:21px; font-weight:600; line-height:1.3; }

#stage .gh-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .gh-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .gh-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .gh-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .gh-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ===================== SCENE 2 · THE WHOLE DIFFERENCE ================== */
#stage .gh-table{ display:flex; flex-direction:column; justify-content:center; gap:12px; height:100%; }
#stage .gh-trow{
  height:118px; flex-shrink:0; display:flex; align-items:center; gap:12px;
}
#stage .gh-trow.head{ height:64px; }
#stage .gh-tk{
  width:180px; flex-shrink:0; text-align:right; padding-right:6px;
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:700;
}
#stage .gh-tv{
  flex:1; min-width:0; height:100%; display:flex; align-items:center; justify-content:center;
  padding:0 14px; border-radius:18px; text-align:center;
  font-size:22px; font-weight:700; line-height:1.25;
}
#stage .gh-tv.grid{ background:rgba(240,166,74,.1); border:1.5px solid rgba(240,166,74,.42); color:#ffe0bd; }
#stage .gh-tv.hubs{ background:rgba(34,211,238,.1); border:1.5px solid rgba(34,211,238,.45); color:#bff2fb; }
#stage .gh-trow.head .gh-tv{
  font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:1.4px;
  background:transparent; border:none;
}
#stage .gh-trow.head .gh-tv.grid{ color:var(--warn); }
#stage .gh-trow.head .gh-tv.hubs{ color:var(--accent-cyan); }

/* ========================== SCENE 3 · THE PAYOFF ======================= */
#stage .gh-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .gh-badges{ display:flex; gap:20px; }
#stage .gh-badge{
  width:120px; height:120px; border-radius:34px; font-size:56px;
  display:flex; align-items:center; justify-content:center;
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .gh-badge.grid{
  background:linear-gradient(160deg, rgba(240,166,74,.3), rgba(240,166,74,.12));
  border:2px solid rgba(240,166,74,.6);
  box-shadow:0 0 0 1px rgba(240,166,74,.28), 0 0 70px rgba(240,166,74,.28);
}
#stage .gh-badge.hubs{
  background:linear-gradient(160deg, rgba(34,211,238,.3), rgba(58,160,255,.12));
  border:2px solid rgba(34,211,238,.6);
  box-shadow:0 0 0 1px rgba(34,211,238,.28), 0 0 70px rgba(34,211,238,.28);
  animation-delay:.5s;
}
#stage .gh-badge-l{ color:var(--text-dim); font-family:var(--font-mono); font-size:20px; font-weight:800; letter-spacing:3px; }
#stage .gh-fin-h{ color:#fff; font-size:52px; font-weight:900; line-height:1.16; letter-spacing:-1.4px; }
#stage .gh-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .gh-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .gh-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.42); color:var(--text-primary);
  font-size:21px; font-weight:700;
}
#stage .gh-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:860px;
  background:linear-gradient(90deg, rgba(240,166,74,.16), rgba(34,211,238,.16));
  border:1.5px solid rgba(34,211,238,.5); color:#fff;
  font-size:24px; font-weight:700; line-height:1.35;
}
#stage .gh-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes gh-push{
  0%{ transform:translateX(-12px); opacity:0; }
  30%{ opacity:1; }
  100%{ transform:translateX(16px); opacity:0; }
}
@keyframes gh-shake{
  0%,88%,100%{ transform:rotate(0deg); }
  91%{ transform:rotate(-14deg); }
  94%{ transform:rotate(12deg); }
  97%{ transform:rotate(-6deg); }
}
@keyframes gh-scrub{
  0%,100%{ transform:translateX(0); }
  50%{ transform:translateX(160px); }
}
@keyframes gh-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

