var GH = window.__GH;

MSD.cls('.gh-sc', 'on', false);
MSD.cls('#gh-sc-board', 'on', true);
MSD.hide('.gh-r');
MSD.cls('.gh-col', 'fade', false);
MSD.cls('#gh-q', 'hot', true);
MSD.q('#gh-qn').textContent = 'MODEL';
MSD.q('#gh-qt').textContent = 'Hold these two pictures';
