MSD.cls('#gh-strip', 'good', false);
MSD.q('#gh-strip-l').textContent = 'MODEL';
MSD.q('#gh-strip-t').textContent = 'If you only remember one thing from this reel, remember these two shapes.';

MSD.after(400, function(){
  MSD.cls('#gh-col-grid', 'lead', true);
  MSD.q('#gh-note-ic').textContent = '🔔';
