});
MSD.after(2500, function(){ MSD.cls('#gh-col-hubs', 'lead', false); });

var GH = window.__GH;

MSD.cls('.gh-sc', 'on', false);
MSD.cls('#gh-sc-board', 'on', true);
MSD.cls('.gh-col', 'fade', false);
MSD.cls('.gh-col', 'lead', false);
MSD.cls('#gh-q', 'hot', true);
MSD.cls('#gh-note', 'both', false);
MSD.q('#gh-qn').textContent = 'Q1';
MSD.q('#gh-qt').textContent = 'One thing, or a series of things?';
MSD.q('#gh-qa').textContent = 'thinking…';
MSD.cls('#gh-qa', 'grid', false);
MSD.cls('#gh-qa', 'hubs', false);
MSD.q('#gh-count-n').textContent = '1';
MSD.cls('#gh-strip', 'good', false);
MSD.q('#gh-strip-l').textContent = 'SHAPE';
MSD.q('#gh-strip-t').textContent = 'Would you ever act on exactly one of these on its own? That is the test.';

MSD.after(400, function(){
