MSD.q('#gh-qn').textContent = 'Q2';
MSD.q('#gh-qt').textContent = 'Who starts the conversation?';
MSD.q('#gh-qa').textContent = 'thinking…';
MSD.cls('#gh-qa', 'grid', false);
MSD.cls('#gh-qa', 'hubs', false);
MSD.q('#gh-count-n').textContent = '2';
MSD.q('#gh-strip-l').textContent = 'DIRECTION';
MSD.q('#gh-strip-t').textContent = 'Push means no consumer to keep alive. Pull means you control the rate.';

MSD.after(400, function(){
  MSD.show('#gh-g-2', 0);
  MSD.cls('#gh-qa', 'grid', true);
