MSD.q('#gh-qt').textContent = 'When delivery fails, who fixes it?';
MSD.q('#gh-qa').textContent = 'thinking…';
MSD.cls('#gh-qa', 'grid', false);
MSD.cls('#gh-qa', 'hubs', false);
MSD.q('#gh-count-n').textContent = '4';
MSD.q('#gh-strip-l').textContent = 'FAILURE';
MSD.q('#gh-strip-t').textContent = 'Nobody expects this one, and it changes how much code you write.';

